#   set the LEVEL WORD's (librec+0x54 -> class 0x3000) low 13 bits to
#   d1 with bit14 cleared and gate the voice off -- the fade-to-level
#   kill used by TgVoiceLevelRampTick
TgVoiceFadeLevelGateOff:
    movm    [d2,d3,a2,a3], (sp)
    add     -0x14, sp
TgVoiceFadeLevelGateOff_entry:
    mov     d0, d3
    mov     d1, a3
    exthu   d0
    mov     0x84, d1
    nop
    nop
    mulu    d1, d0
    mov     d0, a2
    movhu   (0x500ce390), d0
    add     0x500ca0c0, a2
    cmp     0x7f, d0
    beq     loc_4C037A41
    movhu   (a2), d0
    mov     d3, d2
    mov     d0, (0x10, sp)
    mov     d2, d0
    extbu   d0
    clr     d1
    call    TgVoiceRegWrite_entry, [d2,d3], 8
    movhu   (4, a2), d0
    mov     0x00010000, d1
    mov     d0, (0x10, sp)
    mov     d2, d0
    extbu   d0
    call    TgVoiceRegWrite_entry, [d2,d3], 8
    mov     0x54, a1
    add     a2, a1
    mov     (a1), d1
    mov     a3, d0
    exthu   d0
    and     0x1fff, d0
    and     0xffffe000, d1
    or      d1, d0
    mov     d0, (a1)
    and     0xffffbfff, d0
    mov     d0, (0x10, sp)
    extbu   d2
    mov     d2, d0
    exthu   d3
    mov     0x30000000, d1
    call    TgVoiceRegWrite_entry, [d2,d3], 8
    mov     d3, d0
    mov     a2, a0
    call    TgVoiceGateOff_entry, [d2,a2], 0x1c
loc_4C037A41:
    ret     [d2,d3,a2,a3], 0x24
